const title=(eyebrow,h,lead='')=>`<div class="title-group">${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 tabindex="-1">${h}</h1>${lead?`<p class="lead">${lead}</p>`:''}</div>`;
