const mascot=(pose='acolhida',cls='')=>`<img class="mascot ${cls}" src="${asset('stu-'+pose+'.webp')}" alt="" aria-hidden="true">`;
function profileAvatar(d=state){const photo=Object.hasOwn(d,'photo')?d.photo:state.photo;const zoom=Math.min(2.5,Math.max(1,Number(d.photoZoom??state.photoZoom)||1));return photo?`<div class="avatar avatar-photo" data-shape="${(d.photoShape||state.photoShape)==='rounded'?'rounded':'circle'}"><img src="${esc(photo)}" style="transform:scale(${zoom})" alt="Sua foto do perfil"></div>`:`<div class="avatar">${esc(Array.from(d.name||state.name||'N')[0])}</div>`;}
const note=(text,name='info')=>`<div class="note">${icon(name)}<span>${text}</span></div>`;
const row=(name,detail,ico,dest,extra='')=>`<button class="row" type="button" data-go="${dest}" ${extra}><span class="row-icon">${icon(ico)}</span><span class="row-content"><strong>${name}</strong>${detail?`<small>${detail}</small>`:''}</span>${icon('next')}</button>`;
const progress=(value,total,label='Lições concluídas')=>`<div><div class="progress-label"><span>${label}</span><span>${value} de ${total}</span></div><div class="progress" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${value}"><span style="width:${value/total*100}%"></span></div></div>`;
const field=(id,label,value='',type='text',placeholder='')=>`<div><label class="field-label" for="${id}">${label}</label><input class="field" id="${id}" name="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${type==='email'?'autocomplete="email"':type==='password'?'autocomplete="new-password"':'autocomplete="off"'}></div>`;
const lessons=[['WHERE','Inclua o valor no limite','Primeiros passos'],['INNER JOIN','Encontre correspondências','Primeiros passos'],['AND','Combine duas condições','Praticando'],['Filtro + junção','Use as duas ideias juntas','Praticando'],['LEFT JOIN','Preserve linhas sem par','Desafio']];
const course=[
 {title:'O limite também entra.',concept:'WHERE seleciona as linhas que satisfazem uma condição.',detail:'Use >= para incluir valores a partir do limite. O sinal de igualdade faz toda a diferença.',example:'Para notas de pelo menos 7, as notas 7 e 9 entram. A nota 6 fica de fora.',code:'SELECT nome FROM alunos\nWHERE nota >= 7;',goal:'filtros que incluem o valor do limite',feedback:'O sinal de igual inclui Bia, que tem nota exatamente 7. Bia e Caio aparecem.',wrong:'Bia tem nota 7 e também precisa aparecer. Qual operador aceita a igualdade?'},
 {title:'Encontre o que combina.',concept:'INNER JOIN combina linhas de duas tabelas quando a condição em ON é satisfeita.',detail:'A chave liga cada linha ao seu par. Só as correspondências entram no resultado.',example:'Ana tem id 1. Bia tem id 2. A única matrícula tem aluno_id 2: ela corresponde a Bia.',code:'SELECT alunos.nome\nFROM alunos INNER JOIN matriculas\nON alunos.id = matriculas.aluno_id;',question:'Qual nome aparece no resultado?',options:[['Apenas Ana','ana'],['Apenas Bia','bia'],['Ana e Bia','ambas']],correct:'bia',goal:'correspondências entre duas tabelas',feedback:'O id 2 de Bia corresponde ao aluno_id 2 da matrícula.',wrong:'Compare os dois identificadores. Apenas o id de Bia tem um par na matrícula.'},
 {title:'Duas condições, ao mesmo tempo.',concept:'AND combina dois testes no WHERE.',detail:'Uma linha entra somente quando os dois testes são verdadeiros.',example:'O caderno custa 24 e tem estoque 2. O lápis custa 5 e tem estoque 1. O estojo custa 30 e tem estoque 5.',code:'SELECT produto FROM itens\nWHERE preco < 30 AND estoque >= 2;',question:'Qual produto passa pelos dois filtros?',options:[['O caderno','caderno'],['O lápis','lapis'],['O estojo','estojo']],correct:'caderno',goal:'duas condições na mesma consulta',feedback:'O caderno custa menos que 30 e tem pelo menos 2 unidades.',wrong:'O lápis não tem estoque suficiente. O estojo custa exatamente 30, e a condição exige menos que 30.'},
 {title:'Relacione e depois filtre.',concept:'Uma consulta pode combinar uma junção com um filtro.',detail:'INNER JOIN liga as linhas. WHERE seleciona as correspondências que atendem à condição.',example:'Joana tem pedidos de 80 e 20. Marcos tem um pedido de 50. O filtro pede total de pelo menos 50.',code:'SELECT clientes.nome\nFROM clientes INNER JOIN pedidos\nON clientes.id = pedidos.cliente_id\nWHERE pedidos.total >= 50;',question:'Quais clientes aparecem?',options:[['Apenas Joana','joana'],['Apenas Marcos','marcos'],['Joana e Marcos','ambos']],correct:'ambos',goal:'junção e filtro na mesma consulta',feedback:'O pedido de 80 de Joana e o de 50 de Marcos atendem à condição.',wrong:'Lembre que >= inclui o valor 50. Joana e Marcos têm pedidos que atendem à condição.'},
 {title:'Quem não tem par também entra.',concept:'LEFT JOIN preserva todas as linhas da tabela à esquerda.',detail:'Sem correspondência, os campos da tabela à direita aparecem como NULL.',example:'Guia tem um empréstimo de id 8. Atlas não tem empréstimo. Os dois livros estão à esquerda da junção.',code:'SELECT livros.titulo, emprestimos.id\nFROM livros LEFT JOIN emprestimos\nON livros.id = emprestimos.livro_id;',question:'Qual resultado inclui os dois livros?',options:[['Só Guia, com empréstimo 8','guia'],['Só Atlas, com empréstimo NULL','atlas'],['Guia com 8 e Atlas com NULL','ambos']],correct:'ambos',goal:'linhas com e sem correspondência',feedback:'LEFT JOIN mantém Guia e Atlas. Para Atlas, o empréstimo é NULL.',wrong:'Comece pelos dois livros à esquerda. A falta de empréstimo não exclui Atlas.'}
];
const lessonIndex=()=>Math.min(4,Math.max(0,Number(state.lessonIndex)||0));
const lessonList=(compact=false)=>`<div class="list plan-list">${lessons.map((l,i)=>`<div class="row"><span class="row-icon">${i+1}</span><div class="row-content"><strong>${l[0]}</strong><small>${l[1]}</small></div>${compact?'':icon('book')}</div>`).join('')}</div>`;
const saved=()=>{if(state.hasPlan&&state.activeTrack)state.tracks[state.activeTrack]={...state.tracks[state.activeTrack],title:state.planTitle,completed:state.completed,reviewNeeded:[...state.reviewNeeded],visibility:state.visibility,publicationStatus:state.publicationStatus||''};try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{}};
function activateTrack(id){saved();const t=state.tracks[id];if(!t)return;state.activeTrack=id;state.planTitle=t.title;state.completed=t.completed;state.reviewNeeded=[...(t.reviewNeeded||[])];state.visibility=t.visibility||'link';state.publicationStatus=t.publicationStatus||'';state.hasPlan=true;state.lessonIndex=Math.min(t.completed,4);state.selected=null;saved();}
function trackRows(others=false){return Object.entries(state.tracks).filter(([id])=>!others||id!==state.activeTrack).map(([id,t])=>`<button class="row library-row" data-track="${esc(id)}"><span class="cover">${icon('book')}</span><span class="row-content"><strong>${esc(t.title)}</strong><small>${t.completed} de 5 lições concluídas</small></span>${icon('next')}</button>`).join('');}
const clearGeneration=()=>{generationTimers.forEach(clearTimeout);generationTimers=[];};
const notify=text=>{const t=document.getElementById('toast');t.textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.textContent='',2600);};
function go(dest,opts={}){
  if(!PAGES[dest])return;
  if(dirty&&page==='editar'&&!opts.force){ask('Sair sem salvar?','Suas alterações ainda não foram aplicadas ao perfil.','Descartar alterações',()=>{dirty=false;state.profileDraft=null;go(dest,{force:true});});return;}
  if(page==='reforco'&&dest==='exercicio'){state.selected=state.originalAnswer??null;delete state.originalAnswer;}
  if(dest==='exercicio'&&lessonIndex()>0)opts.f='multipla';
  if(recording){recording=false;clearInterval(recordInterval);state.explanation=recordDraft;}
  clearGeneration();const u=new URL(location.href);u.searchParams.set('p',dest);u.searchParams.delete('s');u.searchParams.delete('f');
  if(opts.s)u.searchParams.set('s',opts.s);if(opts.f)u.searchParams.set('f',opts.f);
  const index=history.state?.studoo?history.state.index:0;
  history.replaceState({studoo:true,index,page,scenario,format,scroll:document.querySelector('.app-main')?.scrollTop||0},'');
  history.pushState({studoo:true,index:index+1,page:dest,scenario:opts.s||'',format:opts.f||'lacuna',scroll:0},'',u);page=dest;scenario=opts.s||'';format=opts.f||'lacuna';saved();render(true);
}
function ask(h,text,confirm,cb,destructive=false,typed=false){
 const d=document.createElement('dialog');d.className='dialog';d.innerHTML=`<h2 id="dialog-title">${h}</h2><p>${text}</p>${typed?'<label class="field-label" for="confirm-delete">Digite EXCLUIR para confirmar</label><input id="confirm-delete" class="field" autocomplete="off">':''}${btn(confirm,'confirm-dialog',destructive?'primary danger-action':'primary')}${btn('Cancelar','cancel-dialog','quiet')}`;d.setAttribute('aria-labelledby','dialog-title');root.append(d);let opener=document.activeElement;
 d.querySelector('[data-action=confirm-dialog]').onclick=()=>{if(typed&&d.querySelector('input').value!=='EXCLUIR'){d.querySelector('input').setAttribute('aria-invalid','true');d.querySelector('input').focus();return;}d.close();d.remove();cb();};
 d.querySelector('[data-action=cancel-dialog]').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(opener?.isConnected)opener.focus();});d.showModal();d.querySelector(typed?'input':'[data-action=cancel-dialog]').focus();
}
