function topbar(){
 if(['licao','exercicio','reforco','explique','retorno'].includes(page))return `<header class="topbar">${ib('close','Sair da lição','exit-lesson')}<div class="context"><small>${esc(state.planTitle)}</small><strong>${page==='reforco'?'Outro caminho':page==='explique'||page==='retorno'?'Explique ao Stu':`Lição ${lessonIndex()+1} · ${lessons[lessonIndex()][0]}`}</strong></div><div class="progress" role="progressbar" aria-label="Etapas da lição" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${page==='licao'?1:page==='exercicio'||page==='reforco'?2:3}"><span style="width:${page==='licao'?33:page==='exercicio'||page==='reforco'?66:100}%"></span></div></header>`;
 return `<header class="topbar">${ib(['inicio','pedido','explorar','perfil'].includes(page)?'settings':'back',['inicio','pedido','explorar','perfil'].includes(page)?'Preferências':'Voltar',['inicio','pedido','explorar','perfil'].includes(page)?'go:preferencias':'back')}<div class="brand"><img src="${asset('logo.png')}" alt="Studoo"></div>${ib(page==='mapa'?'more':'user',page==='mapa'?'Opções da trilha':'Meu perfil',page==='mapa'?'plan-menu':'go:perfil')}</header>`;
}
