function passwordField(id,label){return `<div><label class="field-label" for="${id}">${label}</label><div class="field-wrap"><input class="field" type="password" id="${id}" autocomplete="${id==='password'?'current-password':'new-password'}">${ib('eye','Mostrar senha','show-password')}</div></div>`;}
function actionRow(h,p,i,action,cls=''){return `<button class="row ${cls}" data-action="${action}"><span class="row-icon">${icon(i)}</span><span class="row-content"><strong>${h}</strong><small>${p}</small></span>${icon('next')}</button>`;}
function staticRow(h,p,i){return `<div class="row"><span class="row-icon">${icon(i)}</span><div class="row-content"><strong>${h}</strong><small>${p}</small></div></div>`;}
function libraryRow(h,p,i,dest){return `<button class="row library-row" data-go="${dest}"><span class="cover">${icon(i)}</span><span class="row-content"><strong>${esc(h)}</strong><small>${p}</small></span>${icon('next')}</button>`;}
function homeCard(n){if(direction==='jornada')return `<div class="hero">${mascot('acolhida')}<div class="hero-copy"><span class="eyebrow">Continue sua trilha</span><h2>${esc(state.planTitle)}</h2><p>Seu próximo passo está aqui.</p></div></div><div class="current-lesson"><span class="row-icon">${icon('book')}</span><div><small>Próxima lição · ${n+1} de 5</small><h2>${lessons[n][0]}</h2><small>${lessons[n][1]}</small></div></div>`;
 if(direction==='caderno')return `<div class="hero notebook-hero"><div class="hero-copy"><span class="eyebrow">Caderno aberto</span><h2>${esc(state.planTitle)}</h2>${progress(state.completed,5)}</div>${mascot('estudando')}</div><div class="row bookmark-row"><span class="row-icon">${icon('book')}</span><span class="row-content"><small>Marcador de página · próxima lição</small><strong>${lessons[n][0]} · ${lessons[n][1]}</strong></span></div>`;
 return `<div class="hero focus-hero"><div class="hero-copy"><span class="eyebrow">Continue de onde parou</span><h2>${lessons[n][0]}</h2><p>${lessons[n][1]}</p><div class="focus-progress">${progress(state.completed,5)}</div></div></div>`;}
function mapContent(done){let out='';lessons.forEach((l,i)=>{const review=state.reviewNeeded.includes(i)||(scenario==='vale-rever'&&i===0);if(i===0||lessons[i-1][2]!==l[2])out+=`<div class="route-section">${l[2]}</div>`;out+=`<button class="map-node ${i<done?'done':i===done?'current':'locked'}" data-lesson="${i}" aria-label="${esc(l[0])}: ${i<done?(review?'concluída, vale rever':'concluída, rever'):i===done?'próxima, começar':'bloqueada'}"><span class="node-dot">${icon(i<done?'check':i===done?'book':'lock')}</span><span class="node-copy"><strong>${l[0]}</strong><small>${l[1]}</small>${i<done?(review?'<span class="tag review-note">Vale rever</span>':'<small>Concluída</small>'):i===done?'<span class="tag">Seu próximo passo</span>':''}</span>${i===done?icon('arrow'):''}</button>`;});return `<div class="map ${direction==='jornada'?'map-journey':direction==='caderno'?'map-notebook':'map-focus'}">${out}</div>`;}

function choice(label,value){return `<button class="choice ${state.selected===value?'selected':''}" data-choice="${value}" aria-pressed="${state.selected===value}"><span class="choice-marker"></span><span>${label}</span></button>`;}
function exerciseContent(){const current=course[lessonIndex()];let c=title('Sua vez',lessonIndex()>0?current.question:FORMATS[format],lessonIndex()>0?'Leia a consulta e encontre a correspondência.':format==='lacuna'?'Liste os alunos com nota de pelo menos 7.':'Use a ideia do limite para resolver.');
 if(lessonIndex()>0)c+=`<p>${esc(current.example)}</p><pre class="code">${esc(current.code)}</pre><div class="list">${current.options.map(([t,v])=>choice(esc(t),v)).join('')}</div>`;
 else if(format==='lacuna')c+=`<p>Ana tem 6, Bia tem 7 e Caio tem 9.</p><pre class="code">SELECT nome FROM alunos\nWHERE nota <strong>___</strong> 7;</pre><div class="form-grid">${['>','>=','<','<='].map(x=>choice(esc(x),x)).join('')}</div>`;
 else if(format==='multipla')c+=`<pre class="code">WHERE nota &gt;= 7</pre><div class="list">${choice('Apenas Caio','caio')}${choice('Bia e Caio','bc')}${choice('Ana, Bia e Caio','todos')}</div>`;
 else if(format==='ordenar')c+=`<p>Organize os passos para encontrar alunos com nota de pelo menos 7.</p><div class="list">${state.order.map((x,i)=>`<div class="row"><span class="row-content"><strong>${i+1}. ${x}</strong></span>${ib('up','Mover '+x+' para cima','move-up-'+i)}${ib('down','Mover '+x+' para baixo','move-down-'+i)}</div>`).join('')}</div><p id="ordering-status" class="flow-description" role="status" aria-live="polite">Use as setas. Não é necessário arrastar.</p>`;
 else if(format==='associar')c+=`<div class="stack">${[['Maior que','gt'],['Maior ou igual','gte'],['Menor ou igual','lte']].map(([l,k])=>`<div><label class="field-label" for="pair-${k}">${l}</label><select id="pair-${k}" data-pair="${k}"><option value="">Selecione</option>${['>','>=','<='].map(v=>`<option value="${esc(v)}" ${state.pairs[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}</div>`;
 else if(format==='verdadeiro')c+=`<div class="panel"><p>“A condição nota &gt;= 7 inclui quem tem nota exatamente 7.”</p></div><div class="form-grid">${choice('Verdadeiro','v')}${choice('Falso','f')}</div><div><label class="field-label" for="reason">Por quê?</label><textarea id="reason" class="textarea" placeholder="Pense no sinal de igual.">${esc(state.reason||'')}</textarea></div>`;
 else c+=`<div class="panel"><p>Como você escreveria uma condição para incluir alunos com nota exatamente 7 ou maior?</p></div><div><label class="field-label" for="open-answer">Sua resposta</label><textarea id="open-answer" class="textarea" placeholder="Eu usaria…">${esc(state.openAnswer||'')}</textarea></div><p class="flow-description">Critérios: escolher &gt;= e explicar a inclusão do valor 7.</p>`;
 if(scenario==='acerto')c+=`<div class="feedback correct" role="status"><h2>${icon('check')}Isso mesmo!</h2><p>${esc(current.feedback)}</p></div>`;
 else if(scenario==='erro')c+=`<div class="feedback incorrect" role="alert"><h2>${icon('repeat')}Vamos olhar de novo.</h2><p>${esc(current.wrong)}</p></div>`;
 else c+='<div id="form-message" role="alert"></div>';
 return c;
}
function completionContent(){const n=Math.min(state.completed,4),l=course[lessonIndex()],review=state.reviewNeeded.includes(lessonIndex())||scenario==='vale-rever';let lead=review?'Um passo para rever.':state.completed>=5?'Um caminho construído.':direction==='caderno'?'Mais uma página entendida.':direction==='foco'?'Uma ideia que ficou.':'Um passo bem entendido!';return `${direction==='jornada'?mascot('comemorando','big'):'<div class="completion-mark">'+icon('check')+'</div>'}${title(state.completed>=5?'Trilha concluída':'Lição concluída',lead,'Você praticou '+l.goal+'.')}<div class="save-line">${icon('check')}Progresso confirmado · exemplo local</div>${progress(Math.max(state.completed,1),5)}${review?'<div class="note review-note">'+icon('repeat')+'<span><strong>Vale rever.</strong> Você escolheu seguir sem acertar. Volte a esta lição quando quiser para rever a ideia.</span></div>':''}${state.completed>=5?note('Você pode rever qualquer lição e criar um novo caminho.','book'):`<div class="completion-next"><span class="row-icon">${icon('book')}</span><div><small>Próximo passo</small><strong>${lessons[n][0]}</strong><small>${lessons[n][1]}</small></div>${icon('arrow')}</div>`}<div class="note">${icon('spark')}<span><strong>Leve esta ideia:</strong> ${esc(l.detail)}</span></div><div class="stats"><div class="metric"><strong>${Math.max(state.completed,1)}</strong><span>de 5 lições</span></div><div class="metric"><strong>SQL</strong><span>na prática</span></div><div class="metric"><strong>Seu</strong><span>próximo passo</span></div></div>`;}

function exploreRows(){if(state.blocked||state.reportedProfile)return '<div class="empty"><h2>Novos caminhos aparecem por aqui.</h2><p>Os conteúdos ocultos ou de perfis bloqueados não são exibidos.</p></div>';if(scenario==='seguindo'&&!state.followed)return `<div class="empty"><h2>Encontre quem inspira seu estudo.</h2><p>As trilhas dos perfis que você seguir aparecem aqui.</p>${btn('Explorar todas as trilhas','filter-all','secondary')}</div>`;const all=[['SQL sem complicação','Lia · Tecnologia','book'],['Consultas de SQL no dia a dia','Lia · Tecnologia','compass'],['Primeiros filtros e joins','Lia · Tecnologia','book']];return all.filter(x=>!(state.reportedTitles||[]).includes(x[0])&&(!state.search||x[0].toLowerCase().includes(state.search.toLowerCase()))).map(x=>libraryRow(x[0],x[1],x[2],'previa')).join('')||'<div class="empty"><h2>Nenhuma trilha encontrada.</h2><p>Tente outro termo.</p></div>';}
function staticFeedback(h,p,i){return `<div class="feedback"><h2>${icon(i)}${h}</h2><p>${p}</p></div>`;}
function visibilityChoice(v,h,p,i){return `<button class="choice ${state.visibility===v?'selected':''}" data-visibility="${v}" aria-pressed="${state.visibility===v}">${icon(i)}<span class="row-content"><strong>${h}</strong><small>${p}</small></span><span class="choice-marker"></span></button>`;}
function toggleRow(h,p,k){return `<div class="row"><div class="row-content"><strong>${h}</strong><small>${p}</small></div><button role="switch" class="toggle" aria-label="${h}" aria-checked="${state.settings[k]}" data-toggle="${k}"></button></div>`;}
function scenarioContent(html,foot){
 if(scenario==='expirada'&&page==='codigo')return {html:title('Conferir email','Seu código expirou.','Peça um novo código. O email que você informou continua preservado.')+note(esc(state.email),'mail'),foot:actionButtons(btn('Reenviar código','resend-expired'),btn('Usar outro email','go:cadastro','quiet'))};
 if(scenario==='expirada'&&page==='material')return {html:title('Seu material','Escolha o material de novo.','O arquivo do exemplo não está mais disponível. Seu objetivo foi preservado.')+note('Você pode escolher outro arquivo ou continuar sem material.','paper'),foot:actionButtons(btn('Escolher material','retry-material'),btn('Continuar sem material','go:pedido','quiet'))};
 if(scenario==='vazio'&&page!=='inicio')return {html:title(PAGES[page],'Ainda não há nada aqui.','Você pode voltar e escolher um próximo passo.'),foot:actionButtons(btn('Voltar','back','secondary'))};
 if(scenario==='salvando')return {html:title('Concluindo','Guardando seu progresso.','Seu próximo passo aparece depois da confirmação.')+note('Salvando a lição…','clock'),foot:actionButtons(btn('Aguardando confirmação','noop','primary','disabled'))};
 if(scenario==='salvar-erro')return {html:title('Concluir lição','Seu resultado continua aqui.','A confirmação de salvamento ainda não chegou.')+`<div class="feedback incorrect" role="alert"><h2>${icon('info')}Ainda não foi salvo.</h2><p>Tente de novo antes de sair. A lição não aparece como concluída até a confirmação.</p></div>`+note('Você praticou filtros que incluem o valor do limite.','book'),foot:actionButtons(btn('Tentar salvar de novo','retry-scenario'),btn('Ficar nesta tela','stay-here','quiet'))};
 if(scenario==='longa')return {html:html+`<div class="panel"><h2>Um pouco mais de contexto</h2><p>${'Uma consulta fica mais clara quando cada condição corresponde à pergunta que você quer responder. '.repeat(8)}</p></div>`,foot};
 const permission=scenario==='permissao'||scenario==='activity',save=scenario==='salvar-erro',expired=scenario==='expirada';
 return {html:`<div class="feedback incorrect" role="alert"><h2>${icon(permission?'mic':'info')}${permission?'Não foi possível acessar.':save?'Ainda não foi salvo.':expired?'Esta proposta expirou.':'Não foi possível continuar.'}</h2><p>${permission?'Você pode continuar por texto ou escolher outro arquivo.':save?'Seu resultado continua nesta tela. Tente salvar de novo antes de sair.':expired?'Seu objetivo foi preservado. Gere uma nova proposta para começar.':'Seu pedido foi preservado. Confira a conexão e tente novamente.'}</p></div>`+html,foot:actionButtons(btn(permission?'Continuar sem permissão':expired?'Gerar nova proposta':save?'Tentar salvar de novo':'Tentar novamente','retry-scenario'),btn('Voltar','back','quiet'))};
}
function render(focusHeading=false){
 const active=document.activeElement,oldScroll=root.querySelector('.app-main')?.scrollTop||0;
 let restore=null;if(active&&root.contains(active)){for(const k of ['action','choice','interest','hue','visibility','toggle','lesson']){if(active.dataset[k]!==undefined){restore=`[data-${k}="${CSS.escape(active.dataset[k])}"]`;break;}}if(active.id)restore='#'+CSS.escape(active.id);}
 document.documentElement.dataset.reduced=state.settings.movimento?'true':'false';
 const {html,foot,active:activeNav}=mainPage();root.innerHTML=topbar()+`<main class="app-main" id="main"><section class="screen${focusHeading?' screen-enter':''}" data-page="${page}" aria-label="${PAGES[page]}">${html}</section></main>`+foot+(activeNav?nav(activeNav):'');
 const u=new URL(location.href);u.searchParams.set('p',page);if(scenario)u.searchParams.set('s',scenario);else u.searchParams.delete('s');if(page==='exercicio'&&format!=='lacuna')u.searchParams.set('f',format);else u.searchParams.delete('f');
 const index=history.state?.studoo?history.state.index:0;const entry={studoo:true,index,page,scenario,format,scroll:focusHeading?0:oldScroll};
 try{history.replaceState(entry,'',u);}catch{}renderedURL=location.href;renderedState=entry;
 document.title=`${PAGES[page]} · ${direction==='jornada'?'Jornada Azul':direction==='caderno'?'Caderno Claro':'Foco Vivo'} · Studoo`;
 if(focusHeading)root.querySelector('h1')?.focus({preventScroll:true});else{root.querySelector('.app-main').scrollTop=oldScroll;if(restore)root.querySelector(restore)?.focus({preventScroll:true});}
 if(window.parent!==window)window.parent.postMessage({type:'studoo-page',page,direction,scenario,format},location.protocol==='file:'?'*':location.origin);
}
function error(text,id='form-message'){const e=document.getElementById(id);if(e)e.innerHTML=`<p class="form-error">${esc(text)}</p>`;else notify(text);}
function changeScenario(s){scenario=s;const u=new URL(location.href);if(s)u.searchParams.set('s',s);else u.searchParams.delete('s');history.replaceState({...history.state,page,scenario,format},'',u);saved();render();}
function beginGeneration(){clearGeneration();go('geracao');if(q.get('capture')==='1')return;generationTimers.push(setTimeout(()=>{if(page==='geracao')go('proposta');},1600));}
function selectedAnswerCorrect(){if(lessonIndex()>0)return state.selected===course[lessonIndex()].correct;if(format==='lacuna')return state.selected==='>=';if(format==='multipla')return state.selected==='bc';if(format==='ordenar')return state.order.join('|')==='Ler a tabela|Filtrar as linhas|Selecionar as colunas';if(format==='associar')return state.pairs.gt==='>'&&state.pairs.gte==='>='&&state.pairs.lte==='<=';if(format==='verdadeiro')return state.selected==='v'&&(state.reason||'').trim().length>=8;return />=|maior ou igual|igual/i.test(state.openAnswer||'')&&(state.openAnswer||'').trim().length>=15;}
function stopRecording(commit=false){const prior=recording?recordDraft:state.explanation||'';recording=false;clearInterval(recordInterval);scenario=commit?'transcricao':'';if(commit)state.explanation=(prior?prior+'\n\n':'')+'Transcrição de exemplo: '+course[lessonIndex()].detail;else state.explanation=prior;saved();render();document.getElementById('explanation')?.focus();if(commit)notify('Transcrição de exemplo pronta para revisar.');}
const actions={
 back:()=>{if(page==='apresentacao'&&state.intro>0){state.intro--;saved();render(true);return;}if(history.state?.studoo&&history.state.index>0)history.back();else go(authPages.includes(page)?'boasvindas':'inicio');},
 'onboarding-next':()=>{if(state.intro>=4)go('interesses');else{state.intro++;saved();render();}},
 'show-password':e=>{const f=e.closest('.field-wrap').querySelector('input');f.type=f.type==='password'?'text':'password';e.setAttribute('aria-label',f.type==='password'?'Mostrar senha':'Ocultar senha');},
 login:()=>{const email=document.getElementById('email').value.trim(),pw=document.getElementById('password').value;if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){error('Confira o email para continuar.');return;}if(pw.length<8){error('Use uma senha de pelo menos 8 caracteres no exemplo.');return;}state.email=email;state.isGuest=false;if(state.name==='Visitante')state.name='Nina';go('inicio');},
 'provider-google':()=>ask('Entrada com Google','Esta é uma proposta visual. Você pode explorar a sessão de exemplo sem usar uma conta real.','Explorar exemplo',()=>{state.isGuest=false;if(state.name==='Visitante')state.name='Nina';go('inicio');}),
 'provider-apple':()=>ask('Entrada com Apple','Esta é uma proposta visual. Você pode explorar a sessão de exemplo sem usar uma conta real.','Explorar exemplo',()=>{state.isGuest=false;if(state.name==='Visitante')state.name='Nina';go('inicio');}),
 guest:()=>{state.isGuest=true;state.name='Visitante';state.hasPlan=false;state.tracks={};state.activeTrack=null;go('pedido');},
 'signup-code':()=>{const e=document.getElementById('email').value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)){error('Confira o email para receber o código.');return;}state.email=e;go('codigo');},
 'verify-code':()=>{if(document.getElementById('code').value.trim()!=='123456'){error('Esse código não confere. No exemplo, use 123456.');return;}state.resetPassword=false;go('senha');},
 resend:()=>notify('Novo código de exemplo: 123456. Nenhum email foi enviado.'),
 'create-account':()=>{if(document.getElementById('new-password').value.length<8){error('Use pelo menos 8 caracteres.');return;}state.isGuest=false;state.name='Nina';state.hasPlan=false;state.tracks={};state.activeTrack=null;go('pedido');},
 'set-new-password':()=>{if(document.getElementById('new-password').value.length<8){error('Use pelo menos 8 caracteres.');return;}state.resetPassword=false;go('entrar');notify('Senha do exemplo redefinida. Você pode entrar.');},
 recover:()=>{const e=document.getElementById('email').value.trim();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)){error('Confira o email para continuar.');return;}state.email=e;state.resetPassword=true;go('recuperar',{s:'enviado'});},
 'use-sql':()=>{state.goal=initial().goal;saved();render();},'example-goal':()=>{document.getElementById('goal').focus();notify('Este percurso demonstra SQL. Você pode ajustar o objetivo mantendo esse tema.');},
 generate:()=>{state.goal=document.getElementById('goal').value.trim();if(state.goal.length<12){error('Conte um pouco mais sobre o que você quer estudar.');return;}if(!/sql|where|join|consulta/i.test(state.goal)){error('Este protótipo navega pelo exemplo de SQL. Use esse tema para conferir a proposta.');return;}saved();if(!state.consent)go('consentimento');else beginGeneration();},
 'allow-ai':()=>{state.consent=true;saved();beginGeneration();},'cancel-generation':()=>{clearGeneration();go('pedido');},
 'pick-file':()=>{state.file='revisao-sql.pdf';saved();render();notify('Arquivo de exemplo selecionado.');},camera:()=>ask('Prévia da câmera','A câmera é simulada nesta proposta. Você pode usar uma foto de exemplo ou continuar sem ela.','Usar foto de exemplo',()=>{state.file='anotacoes-sql.jpg';saved();render();}),gallery:()=>{state.file='anotacoes-sql.jpg';saved();render();notify('Imagem de exemplo selecionada.');},'remove-material':()=>{state.file=null;saved();render();},
 'accept-plan':()=>{const duplicate=Object.entries(state.tracks).find(([,t])=>t.objective===state.goal||(t.title==='SQL para a prova'&&state.goal===initial().goal));if(duplicate){ask('Essa trilha já está com você.','Seu progresso foi preservado. Abra sua trilha para continuar ou rever uma lição.','Abrir minha trilha',()=>{activateTrack(duplicate[0]);go('mapa');});return;}saved();state.accepted=true;state.hasPlan=true;state.completed=0;state.reviewNeeded=[];state.visibility='link';state.publicationStatus='';state.lessonIndex=0;state.selected=null;state.planTitle='SQL para a prova';state.activeTrack='criada-'+Date.now();state.tracks[state.activeTrack]={title:state.planTitle,completed:0,objective:state.goal};go('licao');},
 'start-current':()=>{state.lessonIndex=Math.min(state.completed,4);state.selected=null;go('licao');},'review-first':()=>{state.lessonIndex=0;go('licao');},
 'check-answer':()=>{const filled=format==='ordenar'||format==='associar'?format==='ordenar'||Object.keys(state.pairs).length===3:format==='aberta'?(state.openAnswer||'').trim():state.selected;if(!filled){error('Complete sua resposta antes de verificar.');return;}const correct=selectedAnswerCorrect();if(correct)state.reviewNeeded=state.reviewNeeded.filter(i=>i!==lessonIndex());changeScenario(correct?'acerto':'erro');},'retry-answer':()=>changeScenario(''),
 'skip-question':()=>ask('Seguir com um ponto para rever?','A lição ficará marcada como “Vale rever”. Você pode voltar à questão quando quiser.','Seguir e marcar para revisão',()=>{if(!state.reviewNeeded.includes(lessonIndex()))state.reviewNeeded.push(lessonIndex());go('explique');}),'review-current':()=>go('licao'),
 hint:()=>ask('Uma pista',lessonIndex()===0?'“Pelo menos 7” também inclui quem tem exatamente 7. Procure o sinal que inclui a igualdade.':course[lessonIndex()].detail,'Entendi',()=>{}),
 'open-reinforcement':()=>{state.reinforce=0;state.originalAnswer=state.selected;state.selected=null;go('reforco');},'reinforcement-next':()=>{if(state.reinforce<2){state.reinforce++;saved();render();return;}if(state.selected!==(lessonIndex()>0?course[lessonIndex()].correct:'bc')){error(lessonIndex()===0?'Bia tem 7 e Caio tem 9. Pense em quem atende a nota mínima.':course[lessonIndex()].wrong);return;}go('exercicio');notify('Outro caminho concluído. Volte à sua resposta.');},
 'exit-lesson':()=>ask('Pausar este estudo?','Você pode voltar ao mapa e retomar esta lição. O exemplo preserva seu ponto nesta sessão.','Pausar e voltar',()=>go('mapa')),
 record:()=>{if(['permissao','activity'].includes(scenario)){error('Gravação indisponível. Sua explicação por texto foi preservada.');return;}recordDraft=state.explanation||'';recording=true;recordStarted=performance.now();scenario='';render();recordInterval=setInterval(()=>{if(!recording)return;const seconds=Math.floor((performance.now()-recordStarted)/1000),el=document.getElementById('record-time');if(el)el.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(seconds>=180){stopRecording(true);notify('Limite do exemplo alcançado. Revise o texto antes de enviar.');}},500);},'stop-record':()=>stopRecording(true),'cancel-record':()=>stopRecording(false),
 'send-explanation':()=>{state.explanation=document.getElementById('explanation').value.trim();if(state.explanation.length<12){error('Escreva um pouco mais ou conclua sem explicar.');return;}go('retorno');},
 complete:()=>{state.completed=Math.max(state.completed,lessonIndex()+1);state.hasPlan=true;saved();go('conclusao');},'next-lesson':()=>{state.lessonIndex=Math.min(state.completed,4);state.selected=null;go('licao');},
 'filter-all':()=>{scenario='';render();},'filter-following':()=>{scenario='seguindo';render();},'filter-tech':()=>{scenario='';state.search='SQL';saved();render();},
 'add-shared':()=>{const title=state.previewTitle||'SQL sem complicação',id='recebida-'+title.toLowerCase().replace(/[^a-z0-9]/g,'-');if(state.tracks[id]){activateTrack(id);go('mapa');notify('Esta cópia já está nas suas trilhas.');return;}saved();state.hasPlan=true;state.completed=0;state.reviewNeeded=[];state.visibility='link';state.publicationStatus='';state.planTitle=title;state.activeTrack=id;state.tracks[id]={title,completed:0};go('mapa');notify('Cópia adicionada ao exemplo local. Suas outras trilhas foram preservadas.');},thank:()=>{state.thanked=!state.thanked;saved();render();notify(state.thanked?'Valeu enviado no exemplo.':'Valeu desfeito.');},follow:()=>{if(state.isGuest){ask('Entre para seguir perfis.','Você pode continuar explorando sem criar uma conta.','Entrar',()=>go('entrar'));return;}state.followed=!state.followed;saved();render();},
 'change-photo':()=>go('foto'),
 'save-profile':()=>{const n=document.getElementById('profile-name').value.trim(),s=document.getElementById('profile-summary').value.trim();if(!n){error('Diga como você quer aparecer no perfil.');return;}const d=state.profileDraft||{};state.name=n;state.summary=s;state.interests=[...(d.interests||state.interests)];state.profileHue=d.hue||state.profileHue||'azul';for(const key of ['photo','photoZoom','photoShape'])if(Object.hasOwn(d,key))state[key]=d[key];state.profileDraft=null;dirty=false;saved();go('perfil',{force:true});notify('Perfil atualizado no exemplo local.');},
 'cancel-profile':()=>go('perfil'),
 'save-plan':()=>{const t=document.getElementById('plan-title').value.trim();if(!t){error('Dê um nome à trilha.');return;}state.planTitle=t;go('mapa');notify('Nome atualizado no exemplo local.');},'change-cover':()=>ask('Capa e tema','O azul e o livro identificam esta trilha no protótipo.','Manter esta capa',()=>notify('Capa mantida.')),
 'delete-plan':()=>ask('Apagar esta trilha?','A cópia do exemplo será removida. Na implementação, seus links também deixam de abrir esta cópia.','Apagar trilha',()=>{delete state.tracks[state.activeTrack];state.activeTrack=null;state.hasPlan=false;state.completed=0;const next=Object.keys(state.tracks)[0];if(next)activateTrack(next);go('inicio');},true),
 'plan-menu':opener=>{const d=document.createElement('dialog');d.className='dialog';d.setAttribute('aria-labelledby','plan-menu-title');d.innerHTML=`<h2 id="plan-menu-title">Esta trilha</h2>${btn('Configurar trilha','go:configurar','secondary')}${btn('Compartilhar','go:compartilhar','quiet')}${btn('Fechar','close-menu','quiet')}`;root.append(d);d.showModal();d.addEventListener('click',e=>{if(e.target.closest('[data-go]')){d.close();d.remove();}});d.addEventListener('close',()=>{d.remove();if(opener?.isConnected)opener.focus();});},
 'person-menu':opener=>{const d=document.createElement('dialog');d.className='dialog';d.setAttribute('aria-labelledby','person-menu-title');d.innerHTML=`<h2 id="person-menu-title">Cuidar deste espaço</h2>${btn('Denunciar perfil','report-person','secondary')}${btn(state.blocked?'Desbloquear perfil':'Bloquear perfil','block-person','quiet')}${btn('Cancelar','close-menu','quiet')}`;root.append(d);d.showModal();d.addEventListener('close',()=>{d.remove();if(opener?.isConnected)opener.focus();});},'close-menu':e=>e.closest('dialog')?.close(),
 'report-person':e=>{e.closest('dialog')?.close();actions['social-start-profile']();},
 'block-person':e=>{e.closest('dialog')?.close();ask(state.blocked?'Desbloquear Lia?':'Bloquear Lia?',state.blocked?'Você volta a ver este perfil no exemplo.':'Este perfil deixa de interagir com você no exemplo. Você pode desfazer em Segurança.',state.blocked?'Desbloquear':'Bloquear',()=>{state.blocked=!state.blocked;state.followed=false;saved();go('explorar');notify(state.blocked?'Perfil bloqueado no exemplo.':'Bloqueio desfeito.');});},unblock:()=>{state.blocked=false;saved();render();notify('Bloqueio desfeito.');},
 'show-code':()=>{if(social.isLinkHidden(scenario)){notify('Confira o estado da publicação antes de mostrar o código.');go('compartilhar');return;}go('codigostudoo');},
 'copy-link':async()=>{const text='https://studoo.example.test/t/sql-exemplo';try{await navigator.clipboard.writeText(text);notify('Link de exemplo copiado.');}catch{ask('Link de exemplo',text,'Entendi',()=>{});}},
 logout:()=>ask('Sair da conta?','Seu progresso real continuaria na sua conta. Aqui, você sai apenas da sessão de exemplo.','Sair',()=>go('entrar')),
 'ai-privacy':()=>{if(state.consent)ask('Revogar apoio de IA?','Novos pedidos que dependem de IA só continuam depois de uma nova permissão.','Revogar permissão',()=>{state.consent=false;saved();render();});else go('consentimento');},
 'privacy-policy':()=>ask('Política de privacidade','O produto abre a política no navegador do sistema. Esta proposta mantém a navegação local e não envia seus dados.','Voltar ao exemplo',()=>{}),
 'delete-account':()=>ask('Excluir sua conta?','Esta ação remove apenas os dados locais deste protótipo. No produto, a confirmação abrange a conta e seus dados.','Excluir exemplo local',()=>{try{localStorage.removeItem(storageKey);}catch{}state=initial();state.hasPlan=false;state.tracks={};state.activeTrack=null;go('boasvindas');},true,true),
 'contact-support':()=>ask('Falar com suporte','Na implementação, esta ação abre o canal de suporte. No protótipo, nenhum email é enviado.','Voltar ao estudo',()=>{state.isGuest=false;if(state.name==='Visitante')state.name='Nina';go('inicio');}),
 'community-rules':()=>ask('Aprender com respeito','Compartilhe conteúdos que você pode publicar. Não exponha dados pessoais, ataques ou material de outra pessoa.','Entendi',()=>{}),
 'report-issue':()=>ask('Reportar problema','O exemplo demonstra a confirmação e o protocolo. Nenhum relato é enviado a uma equipe real.','Registrar exemplo',()=>notify('Protocolo local: STU-002.')),
 'retry-scenario':()=>{const old=scenario;scenario='';if(old==='salvar-erro'){state.completed=Math.max(state.completed,lessonIndex()+1);page='conclusao';}if(old==='expirada')page='pedido';saved();render(true);notify('Estado recuperado no exemplo.');},'resend-expired':()=>{scenario='';render(true);notify('Novo código do exemplo: 123456.');},'retry-material':()=>{state.file=null;scenario='';render(true);},'stay-here':()=>notify('Seu resultado continua aqui. Tente salvar quando quiser.'),noop:()=>{}
};
const addonApi={getState:()=>state,save:saved,render,go,ask,notify,icon,btn,title,field,asset,activateTrack,getScenario:()=>scenario,setScenario:s=>{scenario=s||'';},markProfileDirty:()=>{dirty=true;}};
const media=window.StudooMedia(addonApi),social=window.StudooSocial(addonApi);
Object.assign(actions,media.actions,social.actions);
root.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-go]');if(!el||el.disabled)return;
 if(el.dataset.track){activateTrack(el.dataset.track);go('mapa');return;}
 if(el.dataset.go){if(el.dataset.go==='previa'){const t=el.querySelector('.row-content strong');if(t)state.previewTitle=t.textContent;}go(el.dataset.go);return;}
 if(el.dataset.choice!==undefined){state.selected=el.dataset.choice;saved();render();return;}
 if(el.dataset.interest){const t=el.dataset.interest;if(page==='editar'){const d=state.profileDraft||{name:state.name,summary:state.summary,interests:[...state.interests],hue:state.profileHue||'azul'},a=d.interests||[...state.interests];d.interests=a.includes(t)?a.filter(x=>x!==t):[...a,t];state.profileDraft=d;dirty=true;}else state.interests=state.interests.includes(t)?state.interests.filter(x=>x!==t):[...state.interests,t];saved();render();return;}
 if(el.dataset.hue){state.profileDraft={name:state.name,summary:state.summary,interests:[...state.interests],...state.profileDraft,hue:el.dataset.hue};dirty=true;saved();render();return;}
 if(el.dataset.lesson!==undefined){const i=Number(el.dataset.lesson);if(i>state.completed){notify('Conclua as lições anteriores para abrir este passo.');return;}state.lessonIndex=i;state.selected=null;go('licao');return;}
 if(el.dataset.visibility){state.visibility=el.dataset.visibility;saved();render();return;}
 if(el.dataset.toggle){const k=el.dataset.toggle;state.settings[k]=!state.settings[k];saved();render();return;}
 const a=el.dataset.action;if(a?.startsWith('move-')){const [,dir,n]=a.split('-'),i=Number(n),j=dir==='up'?i-1:i+1;if(j<0||j>=state.order.length){notify('Este item já está no limite da lista.');return;}const moved=state.order[i];[state.order[i],state.order[j]]=[state.order[j],state.order[i]];saved();render();root.querySelector(`[data-action="move-${dir}-${j}"]`)?.focus({preventScroll:true});document.getElementById('ordering-status').textContent=moved+': posição '+(j+1)+' de '+state.order.length+'.';return;}
 if(actions[a])actions[a](el);
});
root.addEventListener('input',e=>{const {id,value}=e.target;if(id==='goal'){state.goal=value;document.getElementById('goal-count').textContent=value.length+'/800 caracteres';}if(id==='explanation')state.explanation=value;if(id==='reason')state.reason=value;if(id==='open-answer')state.openAnswer=value;if(id==='email')state.email=value;if(id==='profile-name'||id==='profile-summary'){dirty=true;state.profileDraft={...state.profileDraft,name:document.getElementById('profile-name').value,summary:document.getElementById('profile-summary').value};}if(id==='search'){state.search=value;document.getElementById('explore-results').innerHTML=exploreRows();}saved();});
root.addEventListener('input',e=>{media.onInput?.(e);social.onInput?.(e);});
root.addEventListener('change',e=>{if(e.target.dataset.pair){state.pairs[e.target.dataset.pair]=e.target.value;saved();}media.onChange?.(e);social.onChange?.(e);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&recording){stopRecording(false);notify('Gravação de exemplo interrompida. Seu texto foi preservado.');}});
window.addEventListener('popstate',e=>{if(dirty&&page==='editar'){history.pushState(renderedState,'',renderedURL);ask('Sair sem salvar?','Suas alterações ainda não foram aplicadas ao perfil.','Descartar alterações',()=>{dirty=false;state.profileDraft=null;saved();history.back();});return;}clearGeneration();const u=new URLSearchParams(location.search);page=PAGES[u.get('p')]?u.get('p'):'inicio';scenario=u.get('s')||'';format=FORMATS[u.get('f')]?u.get('f'):'lacuna';render(true);if(e.state?.scroll)document.querySelector('.app-main').scrollTop=e.state.scroll;});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type==='studoo-reset'){try{localStorage.removeItem(storageKey);}catch{}state=initial();state.tracks={prova:{title:state.planTitle,completed:1}};state.activeTrack='prova';dirty=false;go('inicio',{force:true});}});
render(true);
